package net.officefloor.hq.app.asof;

import java.time.LocalDate;
import java.util.HashSet;
import java.util.Set;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/**
 * Puts a sheet, inside the caller's transaction, as it stood at the end of a date (see {@link SheetSnapshots#show}),
 * with the date for its today, as the as-of view shows it: its parents whose rates it takes (see Rates) are put as
 * they stood then too, bar a parent whose today was never set (it has no dated history, so it is taken as it stands
 * now) — unless the sheet itself had nothing then, when no parent is taken. So too the sheet it was cloned from, and
 * its parents and source in turn. The caller must roll back.
 */
@Service
public class AsOfState {

    private final SheetSnapshots snapshots;
    private final Settings settings;
    private final SheetClock clock;
    private final Rates rates;

    public AsOfState(SheetSnapshots snapshots, Settings settings, SheetClock clock, Rates rates) {
        this.snapshots = snapshots;
        this.settings = settings;
        this.clock = clock;
        this.rates = rates;
    }

    /** Puts the sheet as it stood at the end of the date; returns whether it had anything to show then. */
    public boolean show(String sheet, LocalDate date) {
        boolean had = snapshots.show(sheet, date);
        Set<String> shown = new HashSet<>(Set.of(sheet));
        for (String from = sheet; !from.isEmpty(); ) {
            String parent = settings.parent(from);
            for (int level = 1; level <= Rate.LEVELS && !parent.isEmpty() && shown.add(parent); level++) {
                if (clock.isSet(parent) || !had) {
                    snapshots.show(parent, date);
                }
                parent = settings.parent(parent);
            }
            from = rates.source(from);
            if (!from.isEmpty() && shown.add(from)) {
                if (clock.isSet(from) || !had) {
                    snapshots.show(from, date);
                }
            } else {
                from = "";
            }
        }
        return had;
    }
}
package net.officefloor.hq.app.asof;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A screen showing the sheet as of a date (?asOf=yyyy-MM-dd on its reads): each read of the sheet runs in a
 * transaction that first puts the sheet as it stood at the end of that date (see {@link AsOfState#show}) and is
 * always rolled back, so every figure the endpoints make is made from that state, with the date for the sheet's
 * today, and nothing is ever written. The sheet's parents whose rates it takes (see Rates) are put as they stood at
 * the end of that date too, bar a parent whose today was never set: it has no dated history, so it is taken as it
 * stands now — unless the sheet itself had nothing then (the date is before its history), when no parent is taken.
 * So too the sheet it was cloned from, and its parents and source in turn.
 * Every change sent while the as-of date is set is refused (see ViewerGuard).
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE + 1)
public class AsOfView extends OncePerRequestFilter {

    public static final String PARAM = "asOf";

    private static final Pattern SHEET = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    private final AsOfState state;
    private final TransactionTemplate transaction;

    public AsOfView(AsOfState state, PlatformTransactionManager transactions) {
        this.state = state;
        this.transaction = new TransactionTemplate(transactions);
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String raw = request.getParameter(PARAM);
        Matcher m = SHEET.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        if (raw == null || raw.isBlank() || !"GET".equals(request.getMethod()) || !m.matches()) {
            chain.doFilter(request, response);
            return;
        }
        LocalDate date;
        try {
            date = LocalDate.parse(raw.trim());
        } catch (DateTimeParseException e) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Not a valid as-of date: " + raw);
            return;
        }
        String sheet = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8);
        try {
            transaction.executeWithoutResult((status) -> {
                status.setRollbackOnly();
                state.show(sheet, date);
                try {
                    chain.doFilter(request, response);
                } catch (IOException | ServletException e) {
                    throw new IllegalStateException(e);
                }
            });
        } catch (IllegalStateException e) {
            if (e.getCause() instanceof IOException io) {
                throw io;
            }
            if (e.getCause() instanceof ServletException se) {
                throw se;
            }
            throw e;
        }
    }
}
package net.officefloor.hq.app.asof;

import java.sql.DatabaseMetaData;
import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.jdbc.core.ConnectionCallback;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/**
 * Every row a sheet holds, kept as its today moves on (sheet_snapshot), so the sheet can be shown as it stood at the
 * end of a date. The tables kept are found on boot: every table with a sheet column (the sheet table by its id) and
 * every table of rows kept per person (a person_id column); each gets a shadow table {@code <table>__ASOF} with the
 * same columns (bar the generated ones) and a snapshot_id. A table added later is kept with no change here.
 */
@Repository
public class SheetSnapshots {

    private static final String SHADOW = "__ASOF";

    /** Tables that are history themselves, never part of what a sheet shows (a sheet note carries its own date). */
    private static final Set<String> SKIP = Set.of("FLYWAY_SCHEMA_HISTORY", "SHEET_STATE", "SHEET_SNAPSHOT",
            "SHEET_NOTE");

    /** A table kept per sheet: its stored columns, how its rows of one sheet are found, and its primary key (null when it
     *  has none kept). */
    private record Kept(String table, String columns, String scope, String key) {
    }

    private final JdbcTemplate jdbc;
    private final SheetClock clock;

    /** In the order a parent comes before the rows that reference it. */
    private volatile List<Kept> kept = List.of();

    public SheetSnapshots(JdbcTemplate jdbc, SheetClock clock) {
        this.jdbc = jdbc;
        this.clock = clock;
    }

    /** Finds the tables kept per sheet and makes their shadow tables (DDL, so once on boot, outside any change). */
    @EventListener(ApplicationReadyEvent.class)
    public synchronized void prepare() {
        List<Kept> found = jdbc.execute((ConnectionCallback<List<Kept>>) (con) -> {
            DatabaseMetaData meta = con.getMetaData();
            Map<String, List<String>> columns = new LinkedHashMap<>();
            try (ResultSet rs = meta.getColumns(null, "PUBLIC", "%", "%")) {
                while (rs.next()) {
                    String table = rs.getString("TABLE_NAME");
                    if (SKIP.contains(table) || table.endsWith(SHADOW)) {
                        continue;
                    }
                    List<String> list = columns.computeIfAbsent(table, (k) -> new ArrayList<>());
                    if (!"YES".equals(rs.getString("IS_GENERATEDCOLUMN"))) {
                        list.add(rs.getString("COLUMN_NAME"));
                    }
                }
            }
            Map<String, Set<String>> parents = new HashMap<>();
            for (String table : columns.keySet()) {
                Set<String> mine = new HashSet<>();
                try (ResultSet rs = meta.getImportedKeys(null, "PUBLIC", table)) {
                    while (rs.next()) {
                        mine.add(rs.getString("PKTABLE_NAME"));
                    }
                }
                mine.remove(table);
                parents.put(table, mine);
            }
            List<Kept> out = new ArrayList<>();
            Set<String> placed = new HashSet<>();
            List<String> left = new ArrayList<>(columns.keySet());
            while (!left.isEmpty()) {
                String next = left.stream().filter((t) -> placed.containsAll(
                        parents.get(t).stream().filter(columns::containsKey).toList())).findFirst().orElse(left.get(0));
                left.remove(next);
                placed.add(next);
                List<String> cols = columns.get(next);
                String scope = "SHEET".equals(next) ? "ID = ?"
                        : cols.contains("SHEET") ? "SHEET = ?"
                        : cols.contains("PERSON_ID") ? "PERSON_ID IN (SELECT ID FROM PERSON WHERE SHEET = ?)" : null;
                List<String> key = new ArrayList<>();
                try (ResultSet rs = meta.getPrimaryKeys(null, "PUBLIC", next)) {
                    while (rs.next()) {
                        key.add(rs.getString("COLUMN_NAME"));
                    }
                }
                if (scope != null) {
                    out.add(new Kept(next, String.join(", ", cols), scope,
                            key.isEmpty() || !cols.containsAll(key) ? null : String.join(", ", key)));
                }
            }
            try (Statement st = con.createStatement()) {
                for (Kept k : out) {
                    st.execute("CREATE TABLE IF NOT EXISTS " + k.table() + SHADOW + " AS SELECT CAST(NULL AS BIGINT)"
                            + " AS SNAPSHOT_ID, " + k.columns() + " FROM " + k.table() + " WHERE FALSE");
                    st.execute("CREATE INDEX IF NOT EXISTS " + k.table() + SHADOW + "_SNAPSHOT ON " + k.table()
                            + SHADOW + " (SNAPSHOT_ID)");
                }
            }
            return out;
        });
        kept = List.copyOf(found);
    }

    /** Keeps every row the sheet holds now, as its today moves from one date to another. */
    public void keep(String sheet, LocalDate from, LocalDate to) {
        GeneratedKeyHolder key = new GeneratedKeyHolder();
        jdbc.update((con) -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO sheet_snapshot (sheet, from_today, to_today) VALUES (?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheet);
            ps.setDate(2, Date.valueOf(from));
            ps.setDate(3, Date.valueOf(to));
            return ps;
        }, key);
        long id = key.getKey().longValue();
        for (Kept k : kept) {
            jdbc.update("INSERT INTO " + k.table() + SHADOW + " (SNAPSHOT_ID, " + k.columns() + ") SELECT ?, "
                    + k.columns() + " FROM " + k.table() + " WHERE " + k.scope(), id, sheet);
        }
    }

    /**
     * Puts the sheet, inside the caller's transaction, as it stood at the end of the date: the rows kept when its today
     * first moved from on or before the date to after it; what it holds now when its today has never moved past the
     * date; nothing when its today was never on or before it. The date then stands in for its today. The caller must
     * roll back. Returns whether the sheet had anything to show then (false when it was put as nothing).
     */
    public boolean show(String sheet, LocalDate date) {
        List<Long> found = jdbc.queryForList("SELECT id FROM sheet_snapshot WHERE sheet = ? AND from_today <= ?"
                + " AND to_today > ? ORDER BY id LIMIT 1", Long.class, sheet, Date.valueOf(date), Date.valueOf(date));
        boolean now = found.isEmpty() && !clock.today(sheet).isAfter(date);
        if (!now) {
            for (int i = kept.size() - 1; i >= 0; i--) {
                Kept k = kept.get(i);
                jdbc.update("DELETE FROM " + k.table() + " WHERE " + k.scope(), sheet);
                // A row moved to another sheet since (keeping its key, as a transferred statement does) is put back
                // here, so it is taken from where it is now.
                if (!found.isEmpty() && k.key() != null) {
                    jdbc.update("DELETE FROM " + k.table() + " WHERE (" + k.key() + ") IN (SELECT " + k.key() + " FROM "
                            + k.table() + SHADOW + " WHERE SNAPSHOT_ID = ?)", found.get(0));
                }
            }
            if (!found.isEmpty()) {
                for (Kept k : kept) {
                    jdbc.update("INSERT INTO " + k.table() + " (" + k.columns() + ") SELECT " + k.columns() + " FROM "
                            + k.table() + SHADOW + " WHERE SNAPSHOT_ID = ?", found.get(0));
                }
            }
        }
        clock.setToday(sheet, date);
        return now || !found.isEmpty();
    }
}
package net.officefloor.hq.app;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.officefloor.hq.app.asof.AsOfView;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.sheet.SheetArchive;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

/**
 * A viewer sees every screen and changes nothing: every write to a sheet (POST or PUT) by a user the sheet makes
 * a viewer is refused with a 400 before any step runs, so nothing is written nor audited. The bulk actions are let
 * through: they refuse each selected item themselves (the claim status rules refuse a viewer), reporting 0 done; so is
 * a viewer's bulk grade and bulk retire, which change no one, and a viewer's generate of planned claims or of periods,
 * which makes none.
 * An archived sheet refuses every write the same way, whoever makes it. So does a screen showing the sheet as of a
 * date (?asOf=), bulk actions included: nothing changes while the as-of date is set.
 * A user's own locale and people-list columns are not a change to the sheet: anyone may choose theirs, whatever the sheet.
 */
@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class ViewerGuard extends OncePerRequestFilter {

    private static final Pattern SHEET_WRITE = Pattern.compile("^/api/sheets/([^/]+)(/.*)?$");

    /** The writes that report per-item counts, so a viewer's press goes through with every item refused. */
    private static final Set<String> BULK = Set.of("/claims/bulk-open", "/claims/bulk-settle", "/claims/bulk-void");

    /** The writes that report a count, so a viewer's press goes through and changes no one (still refused when archived). */
    private static final Set<String> VIEWER_COUNTED = Set.of("/people/bulk-grade", "/people/bulk-retire",
            "/plans/generate", "/periods/generate");

    /** The user's own locale: how the screen shows the sheet to them, never a change to it. */
    private static final String LOCALE = "/locale";

    /** The user's own people-list columns: which cells their screen shows, never a change to the sheet. */
    private static final String COLUMNS = "/columns";

    private final Roles roles;
    private final SheetArchive archive;

    public ViewerGuard(Roles roles, SheetArchive archive) {
        this.roles = roles;
        this.archive = archive;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
            throws ServletException, IOException {
        String method = request.getMethod();
        String user = request.getParameter("user");
        Matcher own = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
        if (own.matches() && (LOCALE.equals(own.group(2)) || COLUMNS.equals(own.group(2)))) {
            chain.doFilter(request, response);
            return;
        }
        if (("POST".equals(method) || "PUT".equals(method)) && request.getParameter(AsOfView.PARAM) != null
                && SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length())).matches()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Nothing changes while the sheet is shown as of a date");
            return;
        }
        if (("POST".equals(method) || "PUT".equals(method)) && user != null) {
            Matcher m = SHEET_WRITE.matcher(request.getRequestURI().substring(request.getContextPath().length()));
            if (m.matches() && !BULK.contains(m.group(2) == null ? "" : m.group(2))) {
                String sheet = URLDecoder.decode(m.group(1), StandardCharsets.UTF_8);
                if (!VIEWER_COUNTED.contains(m.group(2) == null ? "" : m.group(2)) && Role.VIEWER.equals(roles.of(sheet, user))) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "A viewer cannot change the sheet");
                    return;
                }
                if (archive.archived(sheet)) {
                    response.sendError(HttpServletResponse.SC_BAD_REQUEST, "An archived sheet cannot change");
                    return;
                }
            }
        }
        chain.doFilter(request, response);
    }
}
import { useEffect, useRef, useState } from 'react';
import type { FormEvent } from 'react';
import { useQueryClient } from '@tanstack/react-query';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { asString, useSearchParam } from '../../url/useSearchParam';

// The date this screen shows the sheet as of (search param `asof`, so it is this user's screen only). While it is
// set every request carries it (api/http.ts): every read answers as the sheet stood at the end of that date, with
// the date for its today, and every change is refused.
function AsOf() {
  const queryClient = useQueryClient();
  const [asof, setAsof] = useSearchParam('asof', asString);
  const [draft, setDraft] = useState('');
  const shown = useRef(asof);

  // Once the URL carries the new date, everything on screen is read again for it.
  useEffect(() => {
    if (shown.current === asof) return;
    shown.current = asof;
    void queryClient.resetQueries();
  }, [asof, queryClient]);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const date = draft.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(date) && !Number.isNaN(Date.parse(date))) setAsof(date);
  };

  return (
    <form onSubmit={submit}>
      As of: <strong data-testid="sheet-asof">{asof}</strong>{' '}
      <input
        data-testid="asof-date"
        type="text"
        placeholder="yyyy-mm-dd"
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
      />
      <button type="submit" data-testid="asof-set">
        Show as of
      </button>
      <button type="button" data-testid="asof-clear" onClick={() => setAsof(undefined)}>
        Show now
      </button>
    </form>
  );
}

export const contribution = SheetPanels.fill({ order: 1, Component: AsOf });
// The app's fetch surface. A non-2xx REJECTS, so useQuery/useMutation surface the failure instead
// of a silent `if (res.ok)` that leaves the UI showing stale data.
/** A non-2xx answer; `status` lets a form tell one refusal from another. */
export class HttpError extends Error {
  constructor(message: string, readonly status: number) {
    super(message);
  }
}

/** The date the screen shows the sheet as of (search param `asof`), or '' when it shows it as it is now. */
export function currentAsOf(): string {
  const raw = new URLSearchParams(window.location.search).get('asof') ?? '';
  return raw.replace(/^"|"$/g, '');
}

/** Every request carries the screen's as-of date: the server answers each read as the sheet stood then, and
 *  refuses every write while it is set. */
function withAsOf(path: string): string {
  const asOf = currentAsOf();
  return asOf ? `${path}${path.includes('?') ? '&' : '?'}asOf=${encodeURIComponent(asOf)}` : path;
}

async function send<T>(path: string, init?: RequestInit, now = false): Promise<T> {
  const res = await fetch(now ? path : withAsOf(path), init);
  if (!res.ok) {
    throw new HttpError(`${init?.method ?? 'GET'} ${path} -> ${res.status}`, res.status);
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

export function getJson<T>(path: string): Promise<T> {
  return send<T>(path);
}

/** A read answered as the sheet is now, whatever the screen's as-of date. */
export function getJsonNow<T>(path: string): Promise<T> {
  return send<T>(path, undefined, true);
}

export function postJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

export function putJson<T>(path: string, body: unknown): Promise<T> {
  return send<T>(path, {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}
import { createContext, useContext } from 'react';
import { getJson, getJsonNow } from '../api/http';
import { asString, useSearchParam } from '../url/useSearchParam';

/** Set around a part of the screen that shows the sheets as they are now even while the screen shows the sheet as
 *  of a date (the search results). */
export const LiveFigures = createContext(false);

/** The query key and the read a sheet query uses: its own, or, inside {@link LiveFigures} while an as-of date is
 *  set, a key of its own ('live' first) read as the sheet is now. With no as-of date the two are the same query. */
export function useReadScope<K extends readonly unknown[]>(key: K): { key: readonly unknown[]; get: typeof getJson } {
  const live = useContext(LiveFigures);
  const [asof] = useSearchParam('asof', asString);
  return live && asof ? { key: ['live', ...key], get: getJsonNow } : { key, get: getJson };
}
import { createFileRoute } from '@tanstack/react-router';
import { SheetPanels } from '../slots/defs/sheetPanels';
import { SignIn } from '../features/session/SignIn';
import { SheetPicker } from '../features/session/SheetPicker';
import { useCurrentSheet, useCurrentUser } from '../features/session/session';
import { notesQuery } from '../features/notes/notes';
import { claimsKey, claimsPath, type Claim } from '../features/claims/claims';
import { peopleKey, peoplePath, type Person } from '../features/people/people';
import { getJson } from '../api/http';

// The one screen. Sign in, then load a sheet by id; the sheet's panels (filled from sheet.panels)
// show everything kept for that sheet.
// Loading a sheet re-reads its notes, people and claims before the sheet shows as loaded, so the lists on screen are
// the store's as they stand, never the lists cached from an earlier load (or none at all while a read is still on its way).
export const Route = createFileRoute('/')({
  loaderDeps: ({ search }) => ({ sheet: (search as Record<string, unknown>).sheet, asof: (search as Record<string, unknown>).asof }),
  loader: async ({ context, deps }) => {
    if (typeof deps.sheet === 'string' && deps.sheet) {
      // A failed read shows through the panel's own query; it never stops the sheet loading.
      const sheet = deps.sheet;
      await Promise.all([
        context.queryClient.fetchQuery(notesQuery(sheet)),
        context.queryClient.fetchQuery({ queryKey: peopleKey(sheet), queryFn: () => getJson<Person[]>(peoplePath(sheet)) }),
        context.queryClient.fetchQuery({ queryKey: claimsKey(sheet), queryFn: () => getJson<Claim[]>(claimsPath(sheet)) }),
      ].map((read) => read.catch(() => undefined)));
    }
  },
  component: Home,
});

function Home() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();

  if (!user) return <SignIn />;

  return (
    <>
      <p>
        Signed in as <strong data-testid="current-user">{user}</strong>
      </p>
      <SheetPicker />
      {sheet ? (
        // Keyed by sheet so per-sheet form drafts never carry over to another sheet.
        <div key={sheet}>
          <SheetPanels.Slot sheet={sheet} user={user} />
        </div>
      ) : (
        <p data-testid="home-empty">Nothing here yet.</p>
      )}
    </>
  );
}

